head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS11200.xml';
scwin.vMktactCd = '314'; //채권시장조치구분코드
scwin.vIsuCd = '', scwin.hasAttachDoc = '';
scwin.gBndApplId = '', scwin.gProcsStat = '0'; //gProcsStat - 처리상태코드(1:처리중,2:처리완료)	
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; //접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.gIsurCd = '';
scwin.btnStat = new Object();
scwin.vRegYn = 'N';
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 발행기관을 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var dsNm = 'BNS_ISUR_INFO';
    var qryId = 'lds.stf.bnscommon.select.listIsurCd';
    var param = '&{P}V_ISUR_NM=' + $c.stf.getObjectValue(txb_IsurCd);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsurList, dsNm, qryId, param);
    var arrPnl = [pnl_IsurSearch];
    $c.bns.ShowWinArrPnl(arrPnl, grd_IsurList);
};


/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 발행기관별 종목을 조회한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = '';
    var param = '';
    if (scwin.vBndListProcsTpCd == 1) {
        qryId = 'lds.stf.bnsisuchg.select.listAppl';
        param += '&{P}V_DTL_YN=' + '';
        param += '&{P}V_ISUR_CD=' + scwin.gIsurCd;
        param += '&{P}V_ISU_CD=' + scwin.vIsuCd;
    } else {
        qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
        param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
        param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    }
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == 2) {
        $c.cm.ShowWin(grd_List2);
    } else {
        $c.cm.ShowWin(grd_List1);
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 해당 종목의 상세내역을 조회한다.
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var dsNm = 'BNS_ISU_CHG_INFO';
    var qryId = '';
    var param = '';
    if (scwin.vBndListProcsTpCd == 1) {
        qryId = 'lds.stf.bnsisuchg.select.listAppl';
        param += '&{P}V_DTL_YN=' + 'Y';
        param += '&{P}V_ISUR_CD=' + scwin.gIsurCd;
        param += '&{P}V_ISU_CD=' + scwin.vIsuCd;
    } else {
        qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoMiscDelist';
        param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
        param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
        param += '&{P}V_BND_APPL_ID=' + scwin.gBndApplId;
        param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    }
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SeqSearch
 * 설명       : 채권신청번호 생성
 ***********************************************/
scwin.fn_SeqSearch = function() {
    var dsNm = 'BNS_BND_APPL_ID_NEXTVAL';
    var qryId = 'lds.stf.bnscommon.select.bndApplIdNextVal';
    var param = '&{P}V_ISUR_CD=' + scwin.gIsurCd;
    dts_NextSeq.SyncLoad = 'true';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_NextSeq, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function(GUBUN) {
    if (GUBUN == 'Acpt') {
        if ($c.stf.getObjectValue(edt_StrtDd) == '') {
            $c.win.alert("[폐지일]을 입력하십시오.");
            edt_StrtDd.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_StrtDd, "폐지일")) {
            return false;
        }
        if ($c.stf.getObjectValue(txb_DlstRsn) == '') {
            $c.win.alert("[폐지사유]를 입력하십시오.");
            txb_DlstRsn.focus();
            return false;
        }
        //if (! checkMaxLength(txb_DlstRsn, 60, '폐지사유') ) return false;

        if ($c.stf.getObjectValue(txb_MemoContn) == '') {
            $c.win.alert("[관련근거]를 입력하십시오.");
            txb_MemoContn.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '관련근거')) return false;
    } else {
        if ($c.stf.getObjectValue(edt_StrtDd2) == '') {
            $c.win.alert("[폐지일]을 입력하십시오.");
            edt_StrtDd2.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_StrtDd2, "폐지일")) {
            return false;
        }
        if ($c.stf.getObjectValue(txb_DlstRsn2) == '') {
            $c.win.alert("[폐지사유]를 입력하십시오.");
            txb_DlstRsn2.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_MemoContn2) == '') {
            $c.win.alert("[관련근거]를 입력하십시오.");
            txb_MemoContn2.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_MemoContn2, 200, '관련근거')) return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_AcptProcsCheck
 * 설명      : 접수, 처리완료시 공통 체크 구문
 ***********************************************/
scwin.fn_AcptProcsCheck = function(gubun) {
    if (gubun == 'Acpt') {
        //필수입력값 체크
        if (scwin.fn_InputCheck('Acpt') == false) return 1;

        //적용일,매매일,마감일,채권마감 체크		
        if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.gBndApplId) > 0) return 1;
    } else if (gubun == 'Procs') {
        //필수입력값 체크
        if (scwin.fn_InputCheck('Proc') == false) return 1;

        //적용일,매매일,마감일,채권마감 체크		
        if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd2), scwin.gBndApplId) > 0) return 1;
    }
    scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
    scwin.hasAttachDoc = dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC");

    //변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    return 0;
};


/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //채권신청ID생성 체크
    if (scwin.gBndApplId == '') {
        $c.win.alert("채권신청ID를 생성하지 못했습니다.");
        return;
    }

    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck('Acpt') > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRule(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;

    //접수		
    if (!confirm("접수처리 하시겠습니까?")) return;
    var url = "/bns/IsuChgEtc.do?method=processApplAcpt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    url += "&NEW_BND_APPL_ID=" + scwin.gBndApplId;
    url += "&REG_YN=" + scwin.vRegYn;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck('Procs') > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRuleProcEnd(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd2)) > 0) return;

    /**
     * 자동 상장제한 폐지사유코드 정의
     */
    var delistCd = $c.stf.getObjectValue(txb_DlstRsn2).substring(0, 2);
    var limit_delistCd = new Array(13);
    var startValue = 05;
    for (var i = 0; i < limit_delistCd.length; i++) {
        limit_delistCd[i] = startValue;
        startValue++;
    }
    var url;
    if (scwin.processGp == '4') {
        //접수 후 수정 및 반송시 체크한다.			
        if ($c.bns.fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.gBndApplId) > 0) return;
        if (!confirm("수정처리 하시겠습니까?")) return;
        /** 
         * 	처리상태가 '처리완료'지 체크
         *	- 해당 O
         *		> 자동 상장제한 페지사유코드에 해당되는지 체크
         *				>> 해당 O
         *					>>> 상장폐지기관에 해당기관이 존재하는지 체크
         *							>>>> 존재 Y
         *									(UPDATE) TBLD_B_BND_APPL, TBLD_B_BND_APPL_DELIST, TBLD_B_DELIST_INST
         *							>>>> 존재 N
         *									(UPDATE) TBLD_B_BND_APPL, TBLD_B_BND_APPL_DELIST
         *									(INSERT) TBLD_B_DELIST_INST
         *				>> 해당 X
         *					(UPDATE) TBLD_B_BND_APPL, TBLD_B_BND_APPL_DELIST
         *	- 해당 X
         *		(UPDATE) TBLD_B_BND_APPL, TBLD_B_BND_APPL_DELIST
         */
        if (scwin.gProcsStat != "2") {
            url = "/bns/IsuChgEtc.do?method=updateAcpt";
        }
    } else {
        if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '처리완료')) return;
        if (dts_DtlInfo.getCellData(1, "REG_YN_ANFEE_REFND") == "N") {
            scwin.fn_GetPar = fn_AnfeeRefnd;
            scwin.fn_SetPar = fn_SetAnfeeRefnd;
            $c.bns.fn_PopAnfeeRefnd(grd_List2);
            if (scwin.vRegYn == "N") return;
        }
        if (scwin.gProcsStat != "2") {
            url = "/bns/IsuChgEtc.do?method=processAcptProcessComplt";
        }
    }
    if (scwin.gProcsStat == "2") {
        if (scwin.processGp == '4') {
            url = "/bns/IsuChgEtc.do?method=updateAcpt";
        } else {
            url = "/bns/IsuChgEtc.do?method=processAcptProcessComplt";
        }
        //폐지사유코드가 "05, 06, 07, 08, 09, 10, 11, 12, 13, 14, 15, 16, 17"인경우에는 자동으로 상장제한으로 등록
        for (var i = 0; i < limit_delistCd.length; i++) {
            //자동 상장제한 페지사유코드에 해당되는 경우
            if (limit_delistCd[i] == delistCd) {
                //상장폐지기관에 해당기관이 존재하는지 체크
                url += "&LIMIT_YN=" + "Y";
                url += "&DELIST_INST_YN=" + dts_DtlInfo.getCellData(1, "IS_YN_DELIST_INST");
                break;
            } else {
                url += "&LIMIT_YN=" + "N";
                break;
            }
        }
    }
    url += "&PROCS_STAT_CD=" + scwin.gProcsStat;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISUR_NM: dts_DtlInfo.getCellData(1, "ISUR_NM"),
        ISU_NM: dts_DtlInfo.getCellData(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetReturn
 * 설명       : 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParApprovFileWrt
 * 설명       : 결재파일생성 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParDelistRsn
 * 설명       : 상장페지 사유선택 (종목)  팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParDelistRsn = function(arrPar) {
    arrPar[0] = {
        BND_DELIST_CD: dts_DtlInfo.getCellData(1, "BND_DELIST_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParDelistRsn
 * 설명       : 상장페지 사유선택 (종목)  팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParDelistRsn = function(arrPar) {
    var getData = arrPar[0].BND_DELIST_CD + " " + arrPar[0].DELIST_RSN_DTL;
    if (scwin.vBndListProcsTpCd == 1) {
        $c.stf.setObjectValue(txb_DlstRsn, getData);
        $c.stf.setObjectValue(txb_MemoContn, arrPar[0].MEMO);
    } else {
        $c.stf.setObjectValue(txb_DlstRsn2, getData);
        $c.stf.setObjectValue(txb_MemoContn2, arrPar[0].MEMO);
    }
};



/********************************************** 
 * 함수명   : fn_AnfeeRefnd
 * 설명       : 연부과금 환급수수료 등록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_AnfeeRefnd = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        MKTACT_TP_CD: scwin.vMktactCd,
        SCREN_ID: scwin.vScrenID
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetAnfeeRefnd
 * 설명       : 연부과금 환급수수료 등록 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetAnfeeRefnd = function(arrPar) {
    scwin.vRegYn = arrPar[0].REG_YN;
    if (scwin.vRegYn == 'Y') {
        scwin.vRowPos = dts_List.getRowPosition();
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_ProcBtnStat
 * 설명       : 처리 상태가 처리완료일 경우, 처리완료 버튼 비활성화
 ***********************************************/
scwin.fn_ProcBtnStat = function() {
    if (scwin.gProcsStat == "2") {
        btn_Proc.src = "../img/bns/btn_20_d.gif";
        scwin.btnStat.Proc = "dis";
    } else {
        btn_Proc.src = "../img/bns/btn_20.gif";
        scwin.btnStat.Proc = "en";
    }
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Req); //패널라운드처리(신청)
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo_Req); //패널라운드처리(신청상세)
    $c.bns.BnsPanelToGroupBox(pnl_IsurSearch); //패널라운드처리(발행기관검색)	
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)	
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo_Acpt); //패널라운드처리(접수상세)		

    tab_List.setSelectedTabIndex(1);

    //팀장확인데이터셋설정	

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Temp.insertRow();

    //발행기관 조회 필드 초기화 및 포커스
    $c.stf.setObjectValue(txb_IsurCd, "");
    txb_IsurCd.focus();
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vBndListProcsTpCd = nIndex;
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (scwin.vBndListProcsTpCd == 2) {
        $c.cm.CloseWin(rowcount, grd_List2);
        //접수,수정,처리완료,팀장확인 시 해당 ROW로 이동
        $c.bns.fn_RowPos(dts_List, scwin.vRowPos);
    } else {
        $c.cm.CloseWin(rowcount, grd_List1);
    }
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (row > 0) {
        if (scwin.vBndListProcsTpCd == 2) {
            scwin.gBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
        } else {
            scwin.vIsuCd = dts_List.getCellData(row, "ISU_CD");
        }
        scwin.fn_dtl_sync();
        scwin.gProcsStat = dts_List.getCellData(row, "PROCS_STAT_CD");
        scwin.fn_ProcBtnStat();
    } else {
        dts_DtlInfo.removeAll();
        scwin.vDtlInfoRowCount = 0;
    }
};
