    if (scwin.vDtlInfoRowCount == 0) return;
    if (dts_DtlInfo.getCellData(1, "REG_YN_ANFEE_REFND") == "Y") {
        $c.win.alert("이미 환급처리되었습니다.");
        return;
    } else {
        scwin.fn_GetPar = fn_AnfeeRefnd;
        scwin.fn_SetPar = fn_SetAnfeeRefnd;
        $c.bns.fn_PopAnfeeRefnd(grd_List2);
    }
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "접수"));
    }
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
    }
    if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    }
    if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "접수"));
        dts_DtlInfo.removeAll();
    }
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        scwin.fn_list_sync();
    }
    if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        scwin.fn_list_sync();
    }
    if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
        scwin.fn_list_sync();
    }
    scwin.vRegYn = 'N';
};
scwin.grd_IsurList_OnClick = function(row, colid) {
    scwin.gIsurCd = dts_IsurList.getCellData(row, "ISUR_CD");
    scwin.fn_list_sync(); //목록 조회

};
